#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized kernel for kernel_size == 2 using float4 vectorized loads.
// Each float4 covers 4 consecutive floats = 2 pool windows of size 2.
// max(v.x, v.y) and max(v.z, v.w) are computed in registers, both added to local_sum.
__global__ void maxpool_sum_scale_kernel_ks2(
    const float* __restrict__ input,
    float* __restrict__ output,
    int width,
    float scale_factor
) {
    int row = blockIdx.x;
    const float* row_ptr = input + row * width;

    float local_sum = 0.0f;

    // float4 path: each float4 = 4 floats = 2 pool windows
    int num_f4 = width >> 2;  // width / 4
    const float4* row_ptr4 = reinterpret_cast<const float4*>(row_ptr);
    for (int i = threadIdx.x; i < num_f4; i += blockDim.x) {
        float4 v = __ldg(&row_ptr4[i]);
        local_sum += fmaxf(v.x, v.y);
        local_sum += fmaxf(v.z, v.w);
    }

    // Scalar tail for remaining elements (when width % 4 != 0)
    int tail_start = num_f4 * 4;
    // process any remaining complete pool windows (pairs)
    for (int i = tail_start + threadIdx.x * 2; i + 1 < width; i += blockDim.x * 2) {
        local_sum += fmaxf(row_ptr[i], row_ptr[i + 1]);
    }

    // Warp-level reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
    }

    // Block-level reduction via shared memory
    __shared__ float warp_sums[32];
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) {
        warp_sums[warp_id] = local_sum;
    }
    __syncthreads();

    int num_warps = (blockDim.x + 31) >> 5;
    if (threadIdx.x < 32) {
        float val = (threadIdx.x < num_warps) ? warp_sums[threadIdx.x] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            val += __shfl_down_sync(mask, val, offset);
